def hands(h, m):
    """smaller angle between clock hands"""
    a = abs(30 * (h % 12) + 0.5 * m - 6 * m) % 360
    return min(a, 360 - a)
assert hands(2, 30) == 105 and hands(3, 30) == 75 and hands(6, 30) == 15 and hands(8, 0) == 120
assert [hands(h, 0) for h in range(1, 12)] == [30, 60, 90, 120, 150, 180, 150, 120, 90, 60, 30]
assert 360 - 275 == 85 and 180 - 115 == 65 and 180 - 40 - 75 == 65 and 5 * 45 == 225

